+    let before = laid_point(&w, Location::default(), [10.0, 10.0, 5.0]);
+    let after = laid_point(&w, a, [10.0, 10.0, 5.0]);
+    assert!(
+        before.iter().zip(after).all(|(p, q)| (p - q).abs() < TIGHT),
